-- Import catalogue Space Marines Warhammer 40,000 (179 produits affichés sur Warhammer.com le 2026-11-04).
-- 172 kits miniatures et 7 ensembles en boîte selon le filtre relevé.
-- Les descriptions sont volontairement vides : à compléter plus tard depuis les fiches produit.
-- Script réexécutable; il ne modifie que les enregistrements portant ces identifiants.
on conflict (id) do update set
  universe=excluded.universe, faction=excluded.faction, name=excluded.name,
  description=case when excluded.description <> '' then excluded.description else catalog_items.description end,
  price_eur=excluded.price_eur, image_url=excluded.image_url, product_url=excluded.product_url,
  price_source=excluded.price_source, price_checked_at=excluded.price_checked_at;
